            // Model v2 parameters. Sources and reasoning: EQIL run report 028, 2026-11-10.
            this.MODEL = {
                relax: 0.3, baseTarget: 50, baseMove: 0.15,
                gateSpan: 15, gateMin: 0.25,
                trustLoss: 1.5, repair: 0.5,
                hotResilience: 0.4, hotTrust: 0.25, coldAdaptive: 0.4,
                vagueTrust: -10, vagueCultural: -5,
                techResilience: -10, techAdaptive: -8, techTrust: -3,
                brokenTrust: -6, brokenCultural: -4,
                drift: { trust: 2.5, resilience: 1, cultural: 1, adaptive: 0.5, financial: 0.1 },
                weights: { trust: 0.20, resilience: 0.20, adaptive: 0.20, cultural: 0.15, financial: 0.10, zone: 0.15 }
