        _t(key, fallback) {
            try {
                if (window.mySimulation && window.mySimulation.t) {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            var tr = this.getTranslations();
            var l = this._lang();
            return (tr[l] && tr[l][key]) || (tr.en && tr.en[key]) || fallback || key;
        }

        _fill(text, map) {
            var out = '' + text;
            Object.keys(map).forEach(function(k) { out = out.split('{' + k + '}').join(map[k]); });
            return out;
        }

        _r2(v) { return Math.round(v * 100) / 100; }

        _newDomainState() {
            return {
                trust: 70,
                temperature: 50,
                resilience: 65,
                financialHealth: 7.0,
                culturalIntegrity: 60,
                adaptiveCapacity: 45,
                trustHistory: [],
                temperatureHistory: [],
                resilienceHistory: [],
                financialHistory: [],
                culturalHistory: [],
                adaptiveHistory: [],
                scoreHistory: [],
                periodsInOptimalZone: 0,
                tempBase: 50,
                flags: { vague: false, promise: false, tech: false, violation: false },
                lastFeedback: null
            };
        }

        initialize(state) {
            var _fresh = !state.history || state.history.length === 0;
            if (_fresh || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = this._newDomainState();
            }
            var ds = state.domainState;
            if (!ds.flags) ds.flags = { vague: false, promise: false, tech: false, violation: false };
            if (typeof ds.tempBase !== 'number') ds.tempBase = 50;
            if (!ds.scoreHistory) ds.scoreHistory = [];
            if (_fresh || !state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice: 1
                };
            }
            this._bindLanguage();
            this._updateBriefing(state);
            this._renderFeedback(state);
        }

        _bindLanguage() {
            if (this._langBound) return;
            this._langBound = true;
            var self = this;
            var repaint = function() {
                try {
                    var st = window.mySimulation && window.mySimulation.state;
                    if (!st) return;
                    var sel = document.getElementById('decisionSelect');
                    var keep = sel ? sel.value : '';
                    var btn = document.getElementById('nextPeriodBtn');
                    var wasDisabled = btn ? btn.disabled : false;
                    self._updateBriefing(st);
                    if (btn) btn.disabled = wasDisabled;
                    sel = document.getElementById('decisionSelect');
                    if (sel && keep) sel.value = keep;
                    self._renderFeedback(st);
                } catch (e) {}
            };
            document.addEventListener('express:langchanged', repaint);
            try {
                if (window.mySimulation && window.mySimulation.eventBus && window.mySimulation.eventBus.on) {
                    window.mySimulation.eventBus.on('language:changed', repaint);
                }
            } catch (e) {}
        }

        validateDecisions(decisions) {
            var _submitBtn = document.getElementById('nextPeriodBtn');
            // the framework disables this button (and marks it data-usf-disabled) before it calls
            // validateDecisions, so only a lock this adapter set itself means re-entry
            if (_submitBtn && _submitBtn.disabled && _submitBtn.getAttribute('data-usf-disabled') !== '1') { return false; }

            var select = document.getElementById('decisionSelect');
            if (select) decisions.choice = parseInt(select.value);
            if (!decisions.choice) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period, phase: r.phase, choice: r.choice, decisionLabel: r.decisionLabel,
                trust: r.trust, temperature: r.temperature, resilience: r.resilience,
                financialHealth: r.financialHealth, culturalIntegrity: r.culturalIntegrity,
                adaptiveCapacity: r.adaptiveCapacity, score: r.score, events: r.events
            };
        }

        // One function scores a run from its per-period series: half the final level and half the
        // average level of each KPI, plus the share of periods that ended inside the 45-65 zone.
        _scoreSeries(S) {
            var n = S.trust.length;
            if (!n) return { score: 0, outcome: 0, process: 0, zonePeriods: 0, periods: 0 };
            var W = this.MODEL.weights;
            var level = function(arr) {
                var sum = 0;
                for (var i = 0; i < arr.length; i++) sum += arr[i];
                return 0.5 * arr[arr.length - 1] + 0.5 * (sum / arr.length);
            };
            var zone = 0;
            for (var i = 0; i < n; i++) { if (S.temperature[i] >= 45 && S.temperature[i] <= 65) zone++; }
            var levels = W.trust * level(S.trust) + W.resilience * level(S.resilience) + W.adaptive * level(S.adaptive) +
                W.cultural * level(S.cultural) + W.financial * level(S.financial) * 10;
            var outcome = levels / (1 - W.zone);
            var process = zone / n * 100;
            var score = levels + W.zone * process;
            return {
                score: Math.max(0, Math.min(100, Math.round(score))),
                outcome: Math.max(0, Math.min(100, Math.round(outcome))),
                process: Math.round(process),
                zonePeriods: zone,
                periods: n
            };
        }

        _tier(score) {
            if (score >= 80) return 'exceptional';
            if (score >= 65) return 'effective';
            if (score >= 50) return 'competent';
            return 'developing';
        }

        _computeRound(state) {
            var M = this.MODEL;
            var ds = state.domainState;
            var d = state.decisions;
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();
            var chosen = null;
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].value === d.choice) {
                    chosen = round.options[i];
                    break;
                }
            }
            if (!chosen) chosen = round.options[0];
            var eff = chosen.effects;
            var events = [];
            var clamp = function(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); };
            var before = { trust: ds.trust, temperature: ds.temperature, resilience: ds.resilience, financial: ds.financialHealth, cultural: ds.culturalIntegrity, adaptive: ds.adaptiveCapacity };

            // 1. The heat the round starts in decides how much of a gain lands (losses always land).
            var t0 = ds.temperature;
            var dist = t0 > 65 ? t0 - 65 : (t0 < 45 ? 45 - t0 : 0);
            var gate = Math.max(M.gateMin, 1 - dist / M.gateSpan);
            if (dist > 0) events.push(t0 > 65 ? 'hot_gate' : 'cold_gate');

            var dT = eff.trust || 0, dR = eff.resilience || 0, dC = eff.cultural || 0, dA = eff.adaptive || 0;
            if (dT > 0) { dT *= gate; if (ds.flags.violation) dT *= M.repair; } else { dT *= M.trustLoss; }
            if (dR > 0) dR *= gate;
            if (dC > 0) dC *= gate;
            if (dA > 0) dA *= gate;

            // 2. Memory: what was said in the first call, and what was left unsolved.
            if (idx === 0) {
                if (chosen.value === 1) ds.flags.vague = true;
                if (chosen.value === 2) ds.flags.promise = true;
            }
            if (idx === 4) {
                if (ds.flags.vague) { dT += M.vagueTrust * M.trustLoss; dC += M.vagueCultural; events.push('vague_collapse'); }
                if (chosen.value !== 2) ds.flags.tech = true;
            }
            if (idx === 11 && ds.flags.tech) { dR += M.techResilience; dA += M.techAdaptive; dT += M.techTrust * M.trustLoss; events.push('tech_return'); }
            if (idx === 7 && chosen.value === 2 && ds.flags.promise) {
                dT += M.brokenTrust * M.trustLoss; dC += M.brokenCultural; ds.flags.violation = true; events.push('broken_promise');
            }

            // 3. Temperature: the first call sets the baseline it settles back to; the baseline moves slowly.
            if (idx === 0) {
                ds.tempBase = 50 + (eff.temperature || 0);
                ds.temperature = clamp(50 + (eff.temperature || 0), 0, 100);
            } else {
                ds.temperature = clamp(ds.tempBase + (t0 - ds.tempBase) * (1 - M.relax) + (eff.temperature || 0), 0, 100);
                ds.tempBase = ds.tempBase + (M.baseTarget - ds.tempBase) * M.baseMove;
            }

            // 4. The crisis erodes every period; ending outside the zone costs more.
            dT -= M.drift.trust; dR -= M.drift.resilience; dC -= M.drift.cultural; dA -= M.drift.adaptive;
            if (ds.temperature > 65) { dR -= (ds.temperature - 65) * M.hotResilience; dT -= (ds.temperature - 65) * M.hotTrust; }
            if (ds.temperature < 45) { dA -= (45 - ds.temperature) * M.coldAdaptive; }

            ds.trust = this._r2(clamp(ds.trust + dT, 0, 100));
            ds.resilience = this._r2(clamp(ds.resilience + dR, 0, 100));
            ds.culturalIntegrity = this._r2(clamp(ds.culturalIntegrity + dC, 0, 100));
            ds.adaptiveCapacity = this._r2(clamp(ds.adaptiveCapacity + dA, 0, 100));
            ds.financialHealth = this._r2(clamp(ds.financialHealth + (eff.financial || 0) - M.drift.financial, 0, 10));
            ds.temperature = this._r2(ds.temperature);
            ds.tempBase = this._r2(ds.tempBase);

            var inZone = ds.temperature >= 45 && ds.temperature <= 65;
            if (inZone) ds.periodsInOptimalZone += 1;

            ds.trustHistory.push(ds.trust);
            ds.temperatureHistory.push(ds.temperature);
            ds.resilienceHistory.push(ds.resilience);
            ds.financialHistory.push(ds.financialHealth);
            ds.culturalHistory.push(ds.culturalIntegrity);
            ds.adaptiveHistory.push(ds.adaptiveCapacity);

            // platform score: the same function the final summary uses, over the periods played so far
            var sc = this._scoreSeries({ trust: ds.trustHistory, resilience: ds.resilienceHistory, adaptive: ds.adaptiveHistory, cultural: ds.culturalHistory, financial: ds.financialHistory, temperature: ds.temperatureHistory });
            ds.scoreHistory.push(sc.score);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: sc.score, outcome: sc.outcome, process: sc.process });

            ds.lastFeedback = {
                period: period,
                events: events,
                score: sc.score,
                deltas: {
                    trust: this._r2(ds.trust - before.trust), temperature: this._r2(ds.temperature - before.temperature),
                    resilience: this._r2(ds.resilience - before.resilience), financial: this._r2(ds.financialHealth - before.financial),
                    cultural: this._r2(ds.culturalIntegrity - before.cultural), adaptive: this._r2(ds.adaptiveCapacity - before.adaptive)
                }
            };
            this._renderFeedback(state);

            // v1.1.0: prevent double-submit re-entrancy (double-applied effects / duplicated
            // history rows). Re-enabled in _updateBriefing when the next period renders.
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn) { _submitBtn.disabled = true; }

            var self = this;
            var nextPeriod = period + 1;
            if (nextPeriod <= (state.maxPeriods || 15)) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);
            }

            return {
                period: period,
                phase: round.phase,
                choice: chosen.value,
                decisionLabel: chosen.label[lang] || chosen.label['en'],
                trust: ds.trust,
                temperature: ds.temperature,
                resilience: ds.resilience,
                financialHealth: ds.financialHealth,
                culturalIntegrity: ds.culturalIntegrity,
                adaptiveCapacity: ds.adaptiveCapacity,
                score: sc.score,
                events: events.join(',')
            };
        }

        _signed(v, digits) {
            var n = Number(v) || 0;
            var s = (digits ? n.toFixed(digits) : String(Math.round(n)));
            if (parseFloat(s) === 0) s = digits ? (0).toFixed(digits) : '0';
            if (this._lang() === 'es') s = s.replace('.', ',');
            return (parseFloat(s.replace(',', '.')) > 0 ? '+' : '') + s;
        }

        _renderFeedback(state) {
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (!feedbackPanel || !feedbackText) return;
            var ds = state && state.domainState;
            var fb = ds && ds.lastFeedback;
            if (!fb) { feedbackPanel.style.display = 'none'; return; }
            var self = this;
            var msgs = [];
            msgs.push(this._fill(this._t('fb_deltas'), {
                p: fb.period,
                t: this._signed(fb.deltas.trust), T: this._signed(fb.deltas.temperature), r: this._signed(fb.deltas.resilience),
                f: this._signed(fb.deltas.financial, 1), c: this._signed(fb.deltas.cultural), a: this._signed(fb.deltas.adaptive), s: fb.score
            }));
            (fb.events || []).forEach(function(ev) { msgs.push(self._t('fb_' + ev)); });
            if (ds.temperature > 65) msgs.push(this._t('hint_high_temp'));
            if (ds.temperature < 45) msgs.push(this._t('hint_low_temp'));
            if (ds.trust < 40) msgs.push(this._t('hint_low_trust'));
            if (ds.financialHealth < 3) msgs.push(this._t('hint_financial_danger'));
            feedbackText.innerHTML = msgs.join('<br>');
            feedbackPanel.style.display = 'block';
        }

