        _seriesFromHistory(history) {
            var S = { trust: [], resilience: [], adaptive: [], cultural: [], financial: [], temperature: [], choice: [], events: [], score: [] };
            (history || []).forEach(function(h) {
                var r = (h && h.results) || {};
                S.trust.push(Number(r.trust) || 0);
                S.resilience.push(Number(r.resilience) || 0);
                S.adaptive.push(Number(r.adaptiveCapacity) || 0);
                S.cultural.push(Number(r.culturalIntegrity) || 0);
                S.financial.push(Number(r.financialHealth) || 0);
                S.temperature.push(typeof r.temperature === 'number' ? r.temperature : 50);
                S.choice.push(Number(r.choice) || 0);
                S.events.push(r.events ? String(r.events).split(',') : []);
                S.score.push(Number(r.score) || 0);
            });
            return S;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var S = this._seriesFromHistory(history);
            var sc = this._scoreSeries(S);
            var n = S.trust.length;
            var last = n - 1;
            var tier = this._tier(sc.score);
            var has = function(i, ev) { return S.events[i] && S.events[i].indexOf(ev) >= 0; };
            var hot = 0, cold = 0;
            for (var i = 0; i < n; i++) { if (S.temperature[i] > 65) hot++; if (S.temperature[i] < 45) cold++; }
            var fallAt = function(i) { return Math.round((i > 0 ? S.trust[i - 1] : 70) - S.trust[i]); };

            // run-specific insights: the mistakes this run made first, then what it did well
            var insights = [];
            if (S.choice[0] === 1) insights.push(this._fill(this._t('ins_vague'), { n: n > 4 ? fallAt(4) : 0 }));
            if (S.choice[0] === 3) insights.push(this._fill(this._t('ins_everything'), { n: n - sc.zonePeriods, m: n }));
            if (n > 7 && has(7, 'broken_promise')) insights.push(this._fill(this._t('ins_broken'), { n: fallAt(7) }));
            else if (n > 7 && S.choice[7] === 2) insights.push(this._fill(this._t('ins_layoff'), { n: fallAt(7) }));
            if (n > 4 && S.choice[4] !== 2) insights.push(this._t('ins_tech'));
            else if (n > 11 && S.choice[11] === 1) insights.push(this._t('ins_tech12'));
            if (hot >= 3) insights.push(this._fill(this._t('ins_hot'), { n: hot }));
            if (cold >= 3) insights.push(this._fill(this._t('ins_cold'), { n: cold }));
            var good = [];
            good.push(this._fill(this._t('ins_zone'), { n: sc.zonePeriods, m: n }));
            if (S.choice[0] === 2 && n > 7 && S.choice[7] !== 2) good.push(this._t('ins_kept'));
            if (n > 11 && S.choice[4] === 2 && S.choice[11] === 2) good.push(this._t('ins_adaptive'));
            good.push(this._t('ins_path'));
            for (var g = 0; g < good.length && insights.length < 5; g++) {
                if (insights.length < 3 || g === 0) insights.push(good[g]);
            }
            insights = insights.slice(0, 5);

            // turning point: the largest fall of the index between two periods, with its cause
            var tpIdx = -1, tpFall = 0;
            for (var k = 1; k < n; k++) {
                var fall = S.score[k - 1] - S.score[k];
                if (fall > tpFall) { tpFall = fall; tpIdx = k; }
            }
            var turningPoint = this._t('tp_none');
            if (tpIdx >= 0 && tpFall >= 2) {
                var rd = this.ROUNDS[Math.min(tpIdx, this.ROUNDS.length - 1)];
                var lang = this._lang();
                var label = '';
                rd.options.forEach(function(o) { if (o.value === S.choice[tpIdx]) label = o.label[lang] || o.label.en; });
                var cause = this._fill(this._t('tp_cause_choice'), { label: label });
                if (has(tpIdx, 'vague_collapse')) cause = this._t('tp_cause_vague');
                else if (has(tpIdx, 'broken_promise')) cause = this._t('tp_cause_broken');
                else if (has(tpIdx, 'tech_return')) cause = this._t('tp_cause_tech');
                else if (S.temperature[tpIdx] > 65) cause = this._fill(this._t('tp_cause_hot'), { label: label });
                else if (S.temperature[tpIdx] < 45) cause = this._fill(this._t('tp_cause_cold'), { label: label });
                turningPoint = this._fill(this._t('tp_fall'), { p: tpIdx + 1, title: rd.title[lang] || rd.title.en, n: tpFall }) + ' ' + cause;
            }

            return {
                cli: sc.score,
                composite: sc.score,
                overallScore: sc.score,
                totalScore: sc.score,
                score: sc.score,
                outcomeScore: sc.outcome,
                processScore: sc.process,
                performance: tier,
                performanceKey: 'perf_' + tier,
                performanceLabel: this._t('perf_' + tier),
                trust: Math.round(S.trust[last]),
                resilience: Math.round(S.resilience[last]),
                adaptiveCapacity: Math.round(S.adaptive[last]),
                culturalIntegrity: Math.round(S.cultural[last]),
                financialHealth: S.financial[last].toFixed(1),
                temperature: Math.round(S.temperature[last]),
                temperatureOptimal: sc.process,
                zonePeriods: sc.zonePeriods,
                periodsPlayed: n,
                turningPoint: turningPoint,
                insights: insights,
                questions: [self._t('dq_1'), self._t('dq_2'), self._t('dq_3')]
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            if (s.overallScore === undefined) {
                return '<div class="pandemic-sim-debrief"><p>' + this._t('db_none') + '</p></div>';
            }
            var esc = function(x) { return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var es = this._lang() === 'es';
            var fin = es ? String(s.financialHealth).replace('.', ',') : String(s.financialHealth);
            var html = '<div class="pandemic-sim-debrief">';
            html += '<p class="pandemic-sim-debrief-score"><strong>' + esc(this._t('db_index')) + ': ' + s.overallScore + '/100</strong> · ' + esc(s.performanceLabel) + '</p>';
            html += '<p>' + esc(this._t('db_outcome')) + ': ' + s.outcomeScore + '/100 · ' + esc(this._t('db_process')) + ': ' + s.processScore + '/100 (' +
                esc(this._fill(this._t('db_zone_count'), { n: s.zonePeriods, m: s.periodsPlayed })) + ')</p>';
            html += '<p>' + esc(this._t('trust_label')) + ' ' + s.trust + ' · ' + esc(this._t('temp_label')) + ' ' + s.temperature + ' · ' + esc(this._t('resilience_label')) + ' ' + s.resilience +
                ' · ' + esc(this._t('financial_label')) + ' ' + fin + ' · ' + esc(this._t('cultural_label')) + ' ' + s.culturalIntegrity + ' · ' + esc(this._t('adaptive_label')) + ' ' + s.adaptiveCapacity + '</p>';
            html += '<h4>' + esc(this._t('db_turning')) + '</h4><p>' + esc(s.turningPoint) + '</p>';
            html += '<h4>' + esc(this._t('db_insights')) + '</h4><ul>';
            (s.insights || []).forEach(function(x) { html += '<li>' + esc(x) + '</li>'; });
            html += '</ul><h4>' + esc(this._t('db_questions')) + '</h4><ol>';
            (s.questions || []).forEach(function(x) { html += '<li>' + esc(x) + '</li>'; });
            html += '</ol></div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.temperature > 65) return this._t('hint_high_temp');
            if (state.domainState.temperature < 45) return this._t('hint_low_temp');
            if (state.domainState.trust < 40) return this._t('hint_low_trust');
            if (state.domainState.financialHealth < 3) return this._t('hint_financial_danger');
            if (state.domainState.adaptiveCapacity < 30) return this._t('hint_low_adaptive');
            return null;
        }

