        _lang() {
            var l = '';
            try { l = (window.vcI18n && window.vcI18n._lang) || ''; } catch (e) {}
            if (!l) l = (window.mySimulation && (window.mySimulation.language || window.mySimulation.currentLanguage)) || document.documentElement.lang || 'es';
            l = ('' + l).substring(0, 2).toLowerCase();
            return (l === 'en') ? 'en' : 'es';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();

            var phaseDisplay = document.getElementById('phaseDisplay');
            if (phaseDisplay) phaseDisplay.textContent = round.phase;

            var phaseNameDisplay = document.getElementById('phaseNameDisplay');
            if (phaseNameDisplay) {
                var names = this.PHASE_NAMES[lang] || this.PHASE_NAMES['es'];
                phaseNameDisplay.textContent = names[round.phase - 1];
            }

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = round.title[lang] || round.title['en'];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing[lang] || round.briefing['en'];

            var select = document.getElementById('decisionSelect');
            if (select) {
                select.innerHTML = '';
                var ph = document.createElement('option');
                ph.value = '';
                ph.textContent = this._t('select_placeholder', '');
                select.appendChild(ph);
                round.options.forEach(function(opt) {
                    var option = document.createElement('option');
                    option.value = opt.value;
                    option.textContent = opt.label[lang] || opt.label['en'];
                    select.appendChild(option);
                });
            }

            // v1.1.0: re-enable submit once the (next) period is on screen.
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn) { _submitBtn.disabled = false; }
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new PandemicLeadershipAdapter(), {
            simulationType: 'pandemic_leadership',
            maxPeriods: 15,
            autoSaveInterval: 30000
        });
    });

})();
